select ok(not exists(select 1 from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v') and has_table_privilege('anon',c.oid,'SELECT')), 'Anon has no table/view SELECT');
select ok(not exists(select 1 from pg_proc p where p.pronamespace in ('public'::regnamespace,'private'::regnamespace) and has_function_privilege('anon',p.oid,'EXECUTE')), 'Anon has no function EXECUTE');
select is((select count(*) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v' and not coalesce(c.reloptions @> array['security_invoker=true'],false)),0::bigint,'Every view uses invoker RLS');
select ok(not exists(select 1 from pg_proc p where p.pronamespace in ('public'::regnamespace,'private'::regnamespace) and p.prorettype in ('trigger'::regtype,'event_trigger'::regtype) and has_function_privilege('authenticated',p.oid,'EXECUTE')), 'All public/private trigger helpers deny authenticated execution');
select ok(not exists(select 1 from pg_proc p where p.pronamespace='public'::regnamespace
 and has_function_privilege('authenticated',p.oid,'EXECUTE')
 and p.proname not in ('registrar_venta','crear_despacho','corregir_devolucion','registrar_devolucion','contar_ventas_jornada')), 'Authenticated RPC allow-list has exactly the frontend endpoints');
