 and not has_table_privilege('authenticated','public.stock_envases','INSERT')
 and not has_table_privilege('authenticated','public.carga_vendedor','DELETE'), 'Balances are database-owned');
select ok(not has_table_privilege('authenticated','public.clientes','DELETE'), 'Client history cannot be deleted');
select ok(not exists (
 select 1 from unnest(array['perfiles','sucursales','productos','tipos_empaque','clientes',
 'carga_vendedor','gastos_extras','ventas','venta_detalles','reglas_comision','despachos',
