 'stock_bodega','stock_envases','producciones','mermas','v_comision_vendedor',
 'v_ranking_vendedores','v_indicadores_produccion_diarios']) obj(name)
 where not has_table_privilege('authenticated','public.' || name,'SELECT')
), 'Every current frontend read and invoker dependency retains SELECT before test-only grants');
