create function pg_temp.fingerprint() returns text language plpgsql as $$
declare t record; result text := ''; h text;
begin
 for t in select tablename from pg_tables where schemaname='public' order by tablename loop
 execute format('select md5(coalesce(string_agg(to_jsonb(r)::text, %L order by to_jsonb(r)::text),%L)) from public.%I r','','',t.tablename) into h;
 result := result || t.tablename || h;
 end loop;
 return md5(result);
end $$;
